Ext.define('BNK.view.common.AuthPopupMViewController', {
    extend: 'Ext.app.ViewController',
    alias: 'controller.common.authpopupm',

    config: {
        viewId: 'InfoPopupM'
    },

    onTextfieldChange: function(field, newValue, oldValue, eOpts) {
        let v = field.getValue().replace(/[^0-9]/g, '');
        field.setValue(v);
    },

    onTextfieldKeyup: function(textfield, e, eOpts) {
        let v = textfield.getValue().replace(/[^0-9]/g, '');
        textfield.setValue(v);
    },

    onSendBtnTap: function(button, e, eOpts) {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();


        var data = {};
        if(Ext.isEmpty(refs.phoneNumber.getValue())){
            Ext.Msg.show({
                buttons :  {
                    yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                },
                title : '모바일 기기 유효성 검증',
                message : '휴대폰번호를 확인해주세요.',
                alwaysOnTop : true,
                fn : function(btn) {
                    return;
                }
            });
            return;
        }
        data.phoneNumber = refs.phoneNumber.getValue().replace(/-/g,'');
        refs.sendBtn.setDisabled(true);

        Ext.Ajax.request({
            headers: {
                viewId: me.getViewId(),
                serviceId: 'BizComSvc.sendAuthNumber'
            },
            jsonData : data,
            scope : me,
            success : function(res) {
                Ext.Viewport.setMasked(false);
                Ext.Msg.show({
                    buttons :  {
                        yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                    },
                    title : '모바일 기기 유효성 검증',
                    message : '인증번호가 발송되었습니다.',
                    alwaysOnTop : true,
                    fn : function(btn) {
                        return;
                    }
                });
            },
            failure : function(res){
                var responseText = Ext.decode(arguments[0].responseText);
                Ext.Msg.show({
                    buttons :  {
                        yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                    },
                    title : '모바일기기 유효성 검증',
                    message : responseText.errMsg,
                    alwaysOnTop : true,
                    fn : function(btn) {
                        return;
                    }
                });
                Ext.Viewport.setMasked(false);
                refs.sendBtn.setDisabled(false);
            }

        });

    },

    onBtnCloseTap: function(button, e, eOpts) {
        this.getView().close();
    },

    onBtnConfirmTap: function(button, e, eOpts) {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();

        var data = {};
        var deviceUuid = '';
        if(Ext.isEmpty(window.device) && 'P'!==Property.PROFILE){
            deviceUuid = 'empty';
        }
        else{
            deviceUuid = device.uuid;
        }
        data.deviceUuid = deviceUuid;
        data.authNumber = refs.authNumber.getValue();
        if(Ext.isEmpty(data.authNumber)||data.authNumber.length<6){
            refs.authNumber.setInputValue('');
            Ext.Msg.show({
                buttons :  {
                    yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                },
                title : '인증번호 유효성 검증',
                message : '인증번호를 다시 입력해주세요',
                alwaysOnTop : true,
                fn : function(btn) {
                    return;
                }
            });
            return;
        }

        Ext.Ajax.request({
            headers: {
                viewId: me.getViewId(),
                serviceId: 'BizComSvc.checkAuthNumber'
            },
            jsonData : data,
            scope : me,
            success : function(res) {
                Ext.Viewport.setMasked(false);
                Ext.Msg.show({
                    buttons :  {
                        yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                    },
                    title : '인증번호 유효성 검증',
                    message : '인증이 완료되었습니다.',
                    alwaysOnTop : true,
                    fn : function(btn) {
                        me.getView().fireEvent('complete');
                        me.getView().close();
                    }
                });
            },
            failure : function(res){
                var responseText = Ext.decode(arguments[0].responseText);
                Ext.Msg.show({
                    buttons :  {
                        yes : {itemId : Ext.MessageBox.YES, text : '확인'}
                    },
                    title : '인증번호 유효성 검증',
                    message : responseText.errMsg,
                    alwaysOnTop : true,
                    fn : function(btn) {
                        return;
                    }
                });
                Ext.Viewport.setMasked(false);
                refs.sendBtn.setDisabled(false);
            }
        });


    },

    onAuthPopupInitialize: function(component, eOpts) {
        var me = this;
        var vm = me.getViewModel();
        var refs = me.getReferences();

        var userId = component.userId;
        var data = {};
        data.userId = userId;

        refs.authLabel1.setHtml(Messages.getMessage('COM001'));
        refs.authLabel2.setHtml(Messages.getMessage('COM002'));

    }

});